/* 昵称与状态 (修正排版：完美停留在头像右侧，Tabs下方) */
.xt-text:nth-of-type(8) {
    display: block !important; padding-top: 10px !important; font-size: 18px !important; font-weight: 800 !important; color: #705854 !important;
