    overflow: hidden !important; /* 建立 BFC 防止环绕错位 */
    width: calc(100% - 86px) !important; /* 强制宽度，绝对不会跑到右上角 */
}
.xt-text:nth-of-type(9) {
    display: block !important; margin-top: 6px !important; font-size: 11px !important; color: #a49e99 !important;
