xinshengCustomCss:
.xt-root {
    /* TikTok 官方暗黑模式 */
    --tk-bg: #000000;
    --tk-text: #ffffff;
    --tk-sub: rgba(255,255,255,0.6);
    --tk-red: #fe2c55;
    --tk-cyan: #25f4ee;

    background: var(--tk-bg) !important; color: var(--tk-text) !important;
    border: 1px solid #222; border-radius: 16px;
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.9);

    /* 🌟核心高度锁定：强制变成修长的全屏视图！ */
    width: 100%; max-width: 400px; height: 550px !important; max-height: 550px !important;
    overflow: hidden; padding: 0; position: relative;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    display: block !important; 
}
.xt-root::-webkit-scrollbar { display: none; }

/* ===================================================== */
/* 🌟 1. 顶部经典导航 (LIVE | STEM | Following | For You | 搜索) */
/* ===================================================== */
.xt-root::before {
    content: "STEM \00a0\00a0\00a0\00a0 Following \00a0\00a0\00a0\00a0 For You";
    display: flex; justify-content: center; align-items: flex-end;
    position: absolute; top: 0; left: 0; width: 100%; height: 60px; padding-bottom: 12px;
    font-size: 15px; font-weight: bold; color: var(--tk-sub); letter-spacing: 0.5px;
    background: linear-gradient(to bottom, rgba(0,0,0,0.8) 0%, transparent 100%);
    z-index: 50; pointer-events: none;

    /* 左侧 LIVE 和右侧搜索 */
    background-image: 
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><rect x='2' y='7' width='20' height='15' rx='2' ry='2'/><polyline points='17 2 12 7 7 2'/><text x='5' y='18' font-size='8' font-family='sans-serif' font-weight='bold' fill='white' stroke='none'>LIVE</text></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><circle cx='11' cy='11' r='8'/><line x1='21' y1='21' x2='16.65' y2='16.65'/></svg>");
    background-repeat: no-repeat; background-size: 24px 24px;
    background-position: 15px 25px, calc(100% - 15px) 25px;
}
.xt-root::after {
    content: ""; position: absolute; top: 55px; left: calc(50% + 25px);
    width: 25px; height: 3px; background: #fff; border-radius: 2px; z-index: 51;
}

/* ===================================================== */
/* 📱 2. 全屏无限垂直滚动引擎 (Scroll-Snap) */
/* ===================================================== */
.xt-content {
    display: block !important; width: 100%; height: 100%; margin: 0; padding: 0;
    overflow-y: auto; overflow-x: hidden; scroll-snap-type: y mandatory;
    -webkit-overflow-scrolling: touch; scrollbar-width: none;
}
.xt-content::-webkit-scrollbar { display: none; }

[id^="xt-t"] { display: none; }
.xt-card-title { display: none !important; }

/* 视频卡片 */
.xt-card {
    width: 100%; height: 100% !important; margin: 0 !important; padding: 0 !important;
    border: none !important; border-radius: 0 !important; box-shadow: none !important;
    scroll-snap-align: start; background: #080808; overflow: hidden;
    position: relative; 
}


/* ===================================================== */
/* 🖱️ 3. 右侧绝对居中的侧边栏交互区 (已修复选择器和高度防重叠) */
/* ===================================================== */

/* 头像：挂红标 */
.xt-header {
    position: absolute !important; bottom: 410px !important; right: 10px !important;
    width: 48px !important; height: 48px !important; margin: 0 !important; padding: 0 !important;
    border: none !important; background: transparent !important; z-index: 50 !important;
}
.xt-header::before, .xt-header::after, .xt-name { display: none !important; }
.xt-avatar {
    width: 48px !important; height: 48px !important; margin: 0 !important; padding: 0 !important;
    background: #333 !important; display: block !important; border-radius: 50% !important; border: 2px solid #fff !important;
    overflow: hidden !important; clip-path: circle(50% at 50% 50%); 
}
.xt-avatar img { width: 100%; height: 100%; object-fit: cover; display: block;}
.xt-header::after {
    content: "+"; position: absolute; bottom: -8px; left: 14px; width: 20px; height: 20px;
    background: var(--tk-red); color: #fff; font-size: 16px; font-weight: bold; border-radius: 50%;
    display: flex !important; align-items: center; justify-content: center; line-height: 1; z-index: 51;
}

/* 核心修复：直接使用生成的类名，并用 padding 挤出图片空间 */
.xt-text-v1Like, .xt-text-v2Like, .xt-text-v3Like,
.xt-text-v1CmtCount, .xt-text-v2CmtCount, .xt-text-v3CmtCount,
.xt-text-v1Fav, .xt-text-v2Fav, .xt-text-v3Fav,
.xt-text-v1Share, .xt-text-v2Share, .xt-text-v3Share {
    position: absolute; right: 10px; width: 50px; 
    font-size: 13px; color: #fff; text-align: center; font-weight: bold; text-shadow: 0 1px 2px #000;
    z-index: 50; margin: 0; padding: 42px 0 0 0; /* 留出 42px 高度放图标！ */
    background-position: top center; background-repeat: no-repeat; background-size: 38px 38px;
}

/* 点赞 */
.xt-text-v1Like, .xt-text-v2Like, .xt-text-v3Like {
    bottom: 330px;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%23fe2c55' stroke='%23fe2c55' stroke-width='1'><path d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z'/></svg>");
}
/* 评论 */
.xt-text-v1CmtCount, .xt-text-v2CmtCount, .xt-text-v3CmtCount {
    bottom: 260px;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='white'><path d='M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm-4 9h-2V9h2v2zm-4 0h-2V9h2v2zm-4 0H6V9h2v2z'/></svg>");
}
/* 收藏 */
.xt-text-v1Fav, .xt-text-v2Fav, .xt-text-v3Fav {
    bottom: 190px;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='white'><path d='M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z'/></svg>");
}
/* 转发 */
.xt-text-v1Share, .xt-text-v2Share, .xt-text-v3Share {
    bottom: 120px;
    background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='white'><path d='M14 3v5c-7 0-11 3-12 11 3-4 6-5 12-5v5l8-8-8-8z'/></svg>");
}


/* ===================================================== */
/* 📝 4. 大字号排版区 (从下至上阶梯式生长) */
/* ===================================================== */

/* 音乐跑马灯区域 (居于底栏上方) */
.xt-text-v1Music, .xt-text-v2Music, .xt-text-v3Music {
    position: absolute; bottom: 65px; left: 15px; width: 60%;
    font-size: 14px; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
    text-shadow: 1px 1px 2px #000; z-index: 50; font-weight: 500;
}
/* 🌟 优化：独立化右下角的旋转黑胶唱片图层 */
.xt-card::before {
    content: ""; position: absolute; bottom: 65px; right: 15px; width: 36px; height: 36px;
    background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24'><circle cx='12' cy='12' r='11' fill='%23222'/><circle cx='12' cy='12' r='4' fill='%23444'/><circle cx='12' cy='12' r='1.5' fill='white'/></svg>") no-repeat center;
    background-size: cover; animation: spin 4s linear infinite; z-index: 49; border-radius: 50%;
}
@keyframes spin { 100% { transform: rotate(360deg); } }

/* 蓝白相间标签 */
.xt-text-vid1Tags, .xt-text-vid2Tags, .xt-text-vid3Tags {
    position: absolute; bottom: 95px; left: 15px; width: 75%;
    font-size: 15px; font-weight: bold; color: #fff; text-shadow: 1px 1px 2px #000; z-index: 50;
}

/* 🌟 小说级剧情描述 */
.xt-text-vid1Desc, .xt-text-vid2Desc, .xt-text-vid3Desc {
    position: absolute; bottom: 130px; left: 15px; width: 75%;
    font-size: 16px; font-weight: normal; color: #fff; text-align: justify;
    line-height: 1.8; padding: 15px 20px; box-sizing: border-box;
    background: radial-gradient(circle at left top, rgba(30,40,50,0.8), transparent 80%);
    border-left: 3px solid var(--tk-cyan); border-radius: 12px;
    text-shadow: 1px 1px 3px rgba(0,0,0,0.8); z-index: 50;
    max-height: 180px; overflow-y: auto; scrollbar-width: none;
}

/* 视频标题 & 伪造 Full Screen 胶囊按钮 (在最顶部) */
.xt-text-vid1Title, .xt-text-vid2Title, .xt-text-vid3Title {
    position: absolute; bottom: 330px; left: 15px; width: 75%;
    font-size: 17px; font-weight: bold; color: #fff; text-shadow: 1px 1px 3px #000; z-index: 50;
}
.xt-text-vid1Title::before, .xt-text-vid2Title::before, .xt-text-vid3Title::before {
    content: "⛶ Full screen"; display: block; width: 100px; text-align: center;
    background: rgba(255,255,255,0.2); padding: 5px 8px; border-radius: 15px; 
    font-size: 12px; color: #fff; margin-bottom: 15px; backdrop-filter: blur(5px);
    box-shadow: 0 1px 4px rgba(0,0,0,0.3); font-weight: normal; font-family: sans-serif;
}


/* ===================================================== */
/* 📱 5. TikTok 底部原生官方导航栏 (文字全部转为内置SVG！) */
/* ===================================================== */
.xt-card::after {
    content: ""; /* 不再使用空格强行对齐，彻底废弃！ */
    position: absolute; bottom: 0; left: 0; width: 100%; height: 55px;
    background: #000; border-top: 1px solid #222; z-index: 150; pointer-events: none;

    /* 终极解法：直接将单词 <text> 写进 SVG 中，保证万年绝对对齐！ */
    background-image: 
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 50'><g transform='translate(8, 2)'><path fill='white' d='M12 3L2 12h3v8h5v-6h4v6h5v-8h3L12 3z'/></g><text x='20' y='42' font-size='10' font-family='sans-serif' font-weight='500' fill='white' text-anchor='middle'>Home</text></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 50'><g transform='translate(8, 2)' fill='none' stroke='%23bbb' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2'/><circle cx='9' cy='7' r='4'/><path d='M23 21v-2a4 4 0 0 0-3-3.87'/><path d='M16 3.13a4 4 0 0 1 0 7.75'/></g><text x='20' y='42' font-size='10' font-family='sans-serif' font-weight='500' fill='%23bbb' text-anchor='middle'>Friends</text></svg>"),
        /* TikTok 重影 ➕ 号 */
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 30'><rect x='5' y='2' width='30' height='26' rx='8' fill='white'/><rect x='3' y='2' width='30' height='26' rx='8' fill='%2325f4ee' style='mix-blend-mode: screen;'/><rect x='7' y='2' width='30' height='26' rx='8' fill='%23fe2c55' style='mix-blend-mode: screen;'/><rect x='5' y='2' width='30' height='26' rx='8' fill='white'/><path d='M19 9v12M13 15h12' stroke='black' stroke-width='3' stroke-linecap='round'/></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 50'><g transform='translate(8, 2)' fill='none' stroke='%23bbb' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z'/></g><text x='20' y='42' font-size='10' font-family='sans-serif' font-weight='500' fill='%23bbb' text-anchor='middle'>Inbox</text></svg>"),
        url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 50'><g transform='translate(8, 2)' fill='none' stroke='%23bbb' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'><path d='M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2'/><circle cx='12' cy='7' r='4'/></g><text x='20' y='42' font-size='10' font-family='sans-serif' font-weight='500' fill='%23bbb' text-anchor='middle'>Profile</text></svg>");
    background-repeat: no-repeat;
    background-size: 40px 50px, 40px 50px, 45px 30px, 40px 50px, 40px 50px;
    background-position: 
        calc(50% - 135px) 5px, 
        calc(50% - 65px) 5px, 
        center 12px, 
        calc(50% + 65px) 5px, 
        calc(50% + 135px) 5px;
}


/* ===================================================== */
/* 💬 6. 弹窗评论区魔法 (支持无限长文本滚动) */
/* ===================================================== */
.xt-action-1, .xt-action-2, .xt-action-3 {
    position: absolute; right: 10px; bottom: 260px; /* 完美遮住下方渲染的评论Icon图标 */
    width: 50px; height: 50px; z-index: 100; opacity: 0; cursor: pointer; display: block !important; margin: 0; padding: 0;
}
/* 将各组的触发热区精准分配 */
.xt-card:nth-of-type(1) .xt-action-1,
.xt-card:nth-of-type(2) .xt-action-2,
.xt-card:nth-of-type(3) .xt-action-3 { display: block !important; }

.xt-card:nth-of-type(1) .xt-action-2, .xt-card:nth-of-type(1) .xt-action-3,
.xt-card:nth-of-type(2) .xt-action-1, .xt-card:nth-of-type(2) .xt-action-3,
.xt-card:nth-of-type(3) .xt-action-1, .xt-card:nth-of-type(3) .xt-action-2 { display: none !important; }

/* 🌟 核心修复：评论区大外框 */
.xt-list { 
    position: absolute; bottom: 0; left: 0; width: 100%; height: 70%;
    background: rgba(30,30,30,0.95); backdrop-filter: blur(10px);
    border-radius: 16px 16px 0 0; padding: 50px 15px 20px; margin: 0; box-sizing: border-box;
    transform: translateY(110%); transition: 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); z-index: 200; border-top: 1px solid #333;
    /* 开启内部独立滚动引擎，隐藏滚动条但允许触摸滑动！ */
    overflow-y: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch;
}
.xt-list::-webkit-scrollbar { display: none; }

/* 伪造顶部固定标题栏 "32.5K Comments" */
.xt-list::before {
    content: "32.5K Comments"; position: fixed; top: 0; left: 0; width: 100%;
    text-align: center; font-size: 13px; font-weight: bold; color: #fff; padding: 15px 0; border-bottom: 1px solid #333;
    background: rgba(30,30,30,0.98); z-index: 10; border-radius: 16px 16px 0 0;
}
.xt-list::after { 
    content: ""; position: fixed; top: 6px; left: calc(50% - 20px); width: 40px; height: 4px; 
    background: #666; border-radius: 2px; z-index: 11;
}

/* 激活评论区 */
#xt-t1:checked ~ .xt-content .xt-card:nth-of-type(1) .xt-list,
#xt-t2:checked ~ .xt-content .xt-card:nth-of-type(2) .xt-list,
#xt-t3:checked ~ .xt-content .xt-card:nth-of-type(3) .xt-list { transform: translateY(0); }

/* 🌟 评论排版优化：不限制高度，自适应文本长度 */
.xt-list-item { 
    position: relative; padding-left: 45px; margin-bottom: 15px; border: none; background: transparent; 
    color: #eaeaea; font-size: 14px; line-height: 1.5; white-space: pre-wrap; box-shadow: none; 
    /* 确保长单词也能换行，不会撑破容器 */
    word-break: break-word; overflow-wrap: break-word;
}
.xt-list-item::first-line { font-size: 13px; font-weight: bold; color: var(--tk-sub); line-height: 2; }
.xt-list-item::before {
    content: "👤"; position: absolute; left: 0; top: 0; width: 32px; height: 32px;
    background: #444; border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-size: 14px; margin: 0; color: #ccc;
}
.xt-list-item::after { content: "♡"; position: absolute; right: 0; top: 5px; color: #888; font-size: 16px; }

/* 🌟 补充魔法：实现“点击弹窗上方空白处关闭评论区”！ */
#xt-t1:checked ~ .xt-content .xt-card:nth-of-type(1) .xt-action-1,
#xt-t2:checked ~ .xt-content .xt-card:nth-of-type(2) .xt-action-2,
#xt-t3:checked ~ .xt-content .xt-card:nth-of-type(3) .xt-action-3 {
    width: 100%; height: 30%; bottom: 70%; right: 0; cursor: pointer;
}

