xinshengCustomCss:
/* --- 1. 基础环境 --- */
.xt-root {
  background: #fffafa !important; 
  --xt-text: #8b7d7d;
  --xt-accent: #ffb7c5;
}
.xt-section, .xt-section-body, .xt-card, .xt-collapse, .xt-collapse-header, .xt-content {
  background: transparent !important;
  border: none !important;
}

/* --- 2. 奶油天平：文字上移 + 缩小 Emoji --- */
.xt-bar {
  margin: 15px 40px !important;
  overflow: visible !important;
  position: relative !important;
}
.xt-bar-label, .xt-bar-value {
  position: absolute !important;
  top: -24px !important;
  font-size: 13px !important;
  color: #b0a0a0 !important;
  font-weight: bold !important;
}
.xt-bar-label { left: 0 !important; }
.xt-bar-value { right: 0 !important; }

.xt-bar-track { background: #f5f5f5 !important; height: 10px !important; border-radius: 10px !important; border: 2px solid #fff !important; }
.xt-bar-fill {
  background: linear-gradient(90deg, #a2d2ff 0%, #ffafbd 100%) !important;
  height: 100% !important; border-radius: 10px !important;
  box-shadow: 0 0 10px rgba(255, 175, 189, 0.3) !important;
}

.xt-bar::before { content: "👼"; position: absolute; left: -32px; top: -3px; font-size: 20px !important; }
.xt-bar::after { content: "👿"; position: absolute; right: -32px; top: -3px; font-size: 20px !important; }

/* --- 3. 灵动飘落核心：彻底打乱下落节奏 --- */
@keyframes wings-fall-organic {
  0% { transform: translateY(-10vh) rotate(0deg) translateX(0); opacity: 0; }
  10% { opacity: 0.5; }
  30% { transform: translateY(30vh) rotate(40deg) translateX(25px); }
  60% { transform: translateY(60vh) rotate(-30deg) translateX(-20px); }
  100% { transform: translateY(105vh) rotate(0deg) translateX(0); opacity: 0; }
}

.xt-particles-stars .xt-particle {
  background: transparent !important;
  font-size: 20px !important;
  animation: wings-fall-organic 12s linear infinite !important; /* 加慢下落总时长 */
  box-shadow: none !important; width: auto !important; height: auto !important;
  position: absolute !important;
}

/* 核心：通过 nth-child 暴力手动分配下落延迟，确保“断断续续” */
.xt-particle:nth-child(1) { left: 15%; animation-delay: 0s; }
.xt-particle:nth-child(2) { left: 80%; animation-delay: -3s; animation-duration: 14s !important; }
.xt-particle:nth-child(3) { left: 45%; animation-delay: -7s; }
.xt-particle:nth-child(4) { left: 10%; animation-delay: -2s; animation-duration: 11s !important; }
.xt-particle:nth-child(5) { left: 90%; animation-delay: -10s; }
.xt-particle:nth-child(6) { left: 30%; animation-delay: -5s; animation-duration: 15s !important; }
.xt-particle:nth-child(7) { left: 70%; animation-delay: -1s; }
.xt-particle:nth-child(8) { left: 55%; animation-delay: -8s; animation-duration: 13s !important; }
.xt-particle:nth-child(9) { left: 25%; animation-delay: -4s; }
.xt-particle:nth-child(10) { left: 85%; animation-delay: -12s; }

/* 翅膀和角的样式 */
.xt-particle:nth-child(odd)::before { content: "ʚɞ"; color: #c2e9fb; opacity: 0.7; }
.xt-particle:nth-child(even)::before { content: "ψ"; color: #ffb7c5; opacity: 0.7; }

/* --- 4. 卡片美化 --- */
.xt-card {
  background: #fff !important;
  border-radius: 15px !important;
  box-shadow: 0 4px 15px rgba(0,0,0,0.02) !important;
  margin-top: 10px !important;
}
.xt-card-title { font-size: 13px !important; font-weight: bold !important; padding-top: 10px !important; }
.angel-card .xt-card-title { color: #90caf9 !important; }
.demon-card .xt-card-title { color: #ef9a9a !important; }

.fake-box .xt-section-body, .true-box .xt-section-body {
  background: #fff !important; border-radius: 12px !important;
  padding: 15px !important; border: 1px solid #fcf2f2 !important;
}
.true-box .xt-section-body { border: 2px dashed #ffb7c5 !important; color: #ff8fa3 !important; }

