xinshengCustomCss:
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@300;400;500;600;700&display=swap');

/* =========================================
   1. 外卡容器（尺寸母体：高度绝对锁死）
   ========================================= */
.xt-root {
    --xt-font: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', 'STSong', serif;
    --letter-ink: #2b4961;       /* 核心墨蓝色 */
    --letter-sub: #788e9e;       /* 核心铅灰副色 */
    --letter-light: #adc0cb;     /* 浅灰蓝 */
    --line-chat: #2b4961;

    background: #ffffff !important;
    border-radius: 4px !important;
    border: none !important;
    box-shadow: 0 10px 35px rgba(43, 73, 97, 0.08) !important;
    padding: 28px 24px 22px 24px !important;
    font-family: var(--xt-font) !important;
    box-sizing: border-box !important;
    position: relative !important;
    overflow: hidden !important;
    height: auto !important;
}

/* =========================================
   2. 首页排版（100% 锁定）
   ========================================= */
.xt-row {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    margin-bottom: 20px !important;
    width: 100% !important;
}

.xt-row > .xt-text-letterTitle {
    flex: 1 !important;
    font-size: 21px !important;
    font-weight: 400 !important;
    color: var(--letter-ink) !important;
    letter-spacing: 2px !important;
    margin: 0 !important;
    padding: 0 !important;
    background: transparent !important;
}

.xt-row .xt-card {
    flex: 0 0 75px !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    margin: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
}

.xt-image {
    width: 60px !important;
    height: 60px !important;
    margin: 0 !important;
    padding: 0 !important;
}

/* 固定指定黑白头像图片 */
.xt-image img {
    content: url('https://pic.feria.eu.org/Qj8yBjRQ/IMG-9440.jpg') !important;
    width: 60px !important;
    height: 60px !important;
    border-radius: 50% !important;
    object-fit: cover !important;
    filter: grayscale(100%) contrast(115%) !important;
    border: 1px solid rgba(43, 73, 97, 0.15) !important;
